import os
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from moler.exceptions import CommandFailure  # type: ignore
from taf.ul.sc.perf.reports.benchmark.excel_generator import ExcelGenerator
from taf.ul.sc.perf.parsers.procdump_parser import ProcdumpParser
from taf.ul.sc.perf.parsers.dsp_parser import DspParser


class BenchmarkExcel(object):
    def __init__(self, log_dir=None, dsp_log_dir=None):
        self.log_dir = log_dir
        self.unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)
        self.dsp_log_dir = dsp_log_dir

    def __call__(self):
        """
        Go through all devices directories gathered during test and generate excel for them
        if they contain appropriate data.
        If path with additional data given add parser, logs path and logs title to list with parsers.
        """
        devices = self._get_all_devices()
        for device in devices:
            try:
                procdump_path = os.path.join(self.log_dir, device, 'benchmark')
                parsers = [{'parser': ProcdumpParser, 'path': procdump_path}]

                if self.dsp_log_dir:
                    dsp_file = "{}{}{}".format('moler.', device, '_DSP.log')
                    dsp_path = os.path.join(self.dsp_log_dir, dsp_file)
                    parsers.append({'parser': DspParser, 'path': dsp_path, 'title': 'load'})

                generator = ExcelGenerator(parsers, '5g')

                generator.generate_excels()
                generator.generate_excels(is_summary=True)

            except (OSError, KeyError) as error:
                MolerTest.warning(msg="Benchmark directory do not exist.")
                MolerTest.warning(msg=error)

    def _get_all_devices(self):
        """
        Make a list with device's directories in log_dir path.
        :return: devices: List with device's names.
        """
        devices = None

        try:
            ls_output = self.unix_local.ls(options="{}".format(self.log_dir))
            devices = ls_output['files'].keys()

        except (CommandFailure, KeyError) as error:
            MolerTest.warning(msg="No BTS available.")
            MolerTest.warning(msg=error)

        return devices
